class Account:
    def __init__(self, owner, balance=0.0):
        self.owner = owner
        self.balance = balance
        self.log = []
    def deposit(self, amt):
        self.balance = self.balance + amt
        self.log.append('+' + str(amt))
        return self.balance
    def withdraw(self, amt):
        if amt > self.balance:
            raise ValueError('insufficient')
        self.balance = self.balance - amt
        self.log.append('-' + str(amt))
        return self.balance
a = Account('ann', 100.0)
print(a.deposit(50.0), a.withdraw(30.0), a.balance)
try:
    a.withdraw(1000.0)
except ValueError as e:
    print('err', e)
print(a.log)

def rle(s):
    if not s:
        return ''
    out = ''
    prev = s[0]
    n = 1
    i = 1
    while i < len(s):
        if s[i] == prev:
            n += 1
        else:
            out += prev + str(n)
            prev = s[i]
            n = 1
        i += 1
    return out + prev + str(n)
print(rle('aaabbc'), rle('abc'), rle(''))

